import{_ as c,C as i,o as e,c as d,a5 as o,b as m,w as a,a as l,E as h,a7 as s}from"./chunks/framework.QWVCgkrI.js";const u=JSON.parse('{"title":"Gitのcommit-graph：なぜ履歴探索で、読まないコミットを増やせるのか","description":"","frontmatter":{"title":"Gitのcommit-graph：なぜ履歴探索で、読まないコミットを増やせるのか","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"tools","summary":"親を読む索引と世代番号を使い、分岐とマージのある履歴でたどる必要のない親を見分ける。コミット時刻が逆転する例も追う。","aliases":["commit-graph","Git commit graph","コミットグラフ索引","世代番号","generation number","corrected committer date"],"verification":"Git公式資料と照合し、WindowsのGit 2.39.2で索引のある場合とない場合の祖先判定、世代番号v1・v2を検証（2026-11-21）"}},"headers":[],"relativePath":"tools/git-commit-graph.md","filePath":"tools/git-commit-graph.md"}'),g={name:"tools/git-commit-graph.md"};function n(p,t,f,E,A,B){const r=i("Mermaid");return e(),d("div",null,[t[1]||(t[1]=o('<h1 id="gitのcommit-graph-なぜ履歴探索で、読まないコミットを増やせるのか" tabindex="-1">Gitのcommit-graph：なぜ履歴探索で、読まないコミットを増やせるのか <a class="header-anchor" href="#gitのcommit-graph-なぜ履歴探索で、読まないコミットを増やせるのか" aria-label="Permalink to &quot;Gitのcommit-graph：なぜ履歴探索で、読まないコミットを増やせるのか&quot;">​</a></h1><p>別ブランチで修正を入れたコミット <code>T</code> が、配布候補のマージコミット <code>M</code> の履歴に含まれるかを確かめます。<code>M</code> から親をたどって <code>T</code> に届けば、<code>T</code> は <code>M</code> の祖先です。履歴が長いと、コミットを開いて親を読む作業が繰り返されます。Gitの <strong>commit-graph</strong> は、親を手早く読むための索引です。さらに世代番号を使うと、親をたどる必要がない箇所を見分けられます。<a href="https://git-scm.com/docs/commit-graph" target="_blank" rel="noreferrer">Gitのcommit-graph設計文書</a></p><h2 id="この記事で分かること" tabindex="-1">この記事で分かること <a class="header-anchor" href="#この記事で分かること" aria-label="Permalink to &quot;この記事で分かること&quot;">​</a></h2><p>commitオブジェクトと再生成できる索引の違いを説明できます。分岐とマージを含む図で、世代番号からどの枝を打ち切れるか、時刻が逆転しても判定できる理由を追えます。</p><h2 id="commitオブジェクトと索引で、何を読むか" tabindex="-1">commitオブジェクトと索引で、何を読むか <a class="header-anchor" href="#commitオブジェクトと索引で、何を読むか" aria-label="Permalink to &quot;commitオブジェクトと索引で、何を読むか&quot;">​</a></h2><p>commitオブジェクトは、親のオブジェクトID（OID）、ルートtree、作者やコミッター、メッセージなどを持ちます。Gitはオブジェクトを展開して読み取れば、親をたどれます。commit-graphには、探索でよく使う親・ルートtree・コミッター時刻と世代番号がまとまっています。Gitは最初のコミットをOIDの順に並べた表から探し、以後は親が指す表の行番号で次の情報を読めます。索引に載ったコミットでは、親を調べるたびに元のオブジェクトを展開して解析する費用を省けます。<a href="https://git-scm.com/docs/commit-graph" target="_blank" rel="noreferrer">Gitのcommit-graph設計文書</a> · <a href="https://git-scm.com/docs/gitformat-commit-graph" target="_blank" rel="noreferrer">Gitのcommit-graphファイル形式</a></p><p>索引を削除しても、元のオブジェクトとブランチの参照が残っていれば、履歴やコミットIDは変わりません。Gitは索引なしでもオブジェクトから親を読めます。たとえば <code>git commit-graph write --reachable</code> は、参照から到達できるコミットをもとに索引を作り直せます。逆に、索引だけからコミットメッセージやファイル内容を復元することはできません。<a href="https://git-scm.com/docs/commit-graph" target="_blank" rel="noreferrer">Gitのcommit-graph設計文書</a> · <a href="https://git-scm.com/docs/git-commit-graph" target="_blank" rel="noreferrer">git commit-graphコマンド</a></p><h2 id="分岐とマージから、親をたどらない枝を見つける" tabindex="-1">分岐とマージから、親をたどらない枝を見つける <a class="header-anchor" href="#分岐とマージから、親をたどらない枝を見つける" aria-label="Permalink to &quot;分岐とマージから、親をたどらない枝を見つける&quot;">​</a></h2><p>図の矢印は子から親に向きます。<code>M</code> は親が2つあるマージコミットです。履歴は、矢印に向きがあり同じ頂点に戻る道がない <strong>DAG</strong>（有向非巡回グラフ）です。数字は世代番号v1です。親のない <code>R</code> は1、ほかは最も大きい親の世代に1を足します。たとえば <code>M</code> は <code>Z</code> の4と <code>Y</code> の3を比べて、<code>max(4, 3) + 1 = 5</code> です。<a href="https://git-scm.com/docs/commit-graph" target="_blank" rel="noreferrer">Gitのcommit-graph設計文書</a></p>',9)),(e(),m(s,null,{default:a(()=>[h(r,{id:"mermaid-27",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20accTitle%3A%20Git%E3%81%AE%E5%B1%A5%E6%AD%B4%E3%81%A8%E4%B8%96%E4%BB%A3%E7%95%AA%E5%8F%B7v1%0A%20%20%20%20accDescr%3A%20M%E3%81%AE%E4%B8%96%E4%BB%A3%E3%81%AF5%E3%81%A7%E8%A6%AA%E3%81%AFZ%EF%BC%884%EF%BC%89%E3%81%A8Y%EF%BC%883%EF%BC%89%E3%80%82Z%E3%81%AE%E8%A6%AA%E3%81%AFX%EF%BC%883%EF%BC%89%E3%80%82%E6%8E%A2%E3%81%99T%EF%BC%884%EF%BC%89%E3%81%AE%E8%A6%AA%E3%81%AFB%EF%BC%883%EF%BC%89%E3%80%82B%E3%80%81X%E3%80%81Y%E3%81%AE%E8%A6%AA%E3%81%AFA%EF%BC%882%EF%BC%89%E3%80%81A%E3%81%AE%E8%A6%AA%E3%81%AFR%EF%BC%881%EF%BC%89%E3%80%82%E7%9F%A2%E5%8D%B0%E3%81%AF%E5%AD%90%E3%81%8B%E3%82%89%E8%A6%AA%E3%80%82%0A%20%20%20%20m%5B%22M%20%C2%B7%205%22%5D%20--%3E%20z%5B%22Z%20%C2%B7%204%22%5D%20--%3E%20x%5B%22X%20%C2%B7%203%22%5D%20--%3E%20a%5B%22A%20%C2%B7%202%22%5D%20--%3E%20r%5B%22R%20%C2%B7%201%22%5D%0A%20%20%20%20m%20--%3E%20y%5B%22Y%20%C2%B7%203%22%5D%20--%3E%20a%0A%20%20%20%20t%5B%22T%20%C2%B7%204%22%5D%20--%3E%20b%5B%22B%20%C2%B7%203%22%5D%20--%3E%20a%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=o('<p><code>T</code>（世代4）が <code>M</code> の祖先かを調べます。世代が4未満のコミットまで来たら、その先へ親をたどっても4には戻れません。ここでは全コミットの世代が計算済みです。次の流れは、候補より小さい世代で打ち切る考え方を示す概念例です。<a href="https://git-scm.com/docs/commit-graph" target="_blank" rel="noreferrer">Gitのcommit-graph設計文書</a></p><ol><li><code>M</code>（5）の親を調べます。<code>Y</code>（3）はそこで打ち切り、<code>Z</code>（4）を調べます。</li><li><code>Z</code> のOIDは <code>T</code> と異なります。<code>Z</code> の親 <code>X</code>（3）も打ち切れるため、<code>A</code> や <code>R</code> まで進む必要はありません。</li><li>どの枝にも <code>T</code> はありません。候補が <code>Z</code> なら、1の時点でOIDが一致して見つかります。世代が同じだけでは、一致したことにはなりません。</li></ol><p>索引にまだ載っていないコミットや、v1の値が上限に達したコミットもあります。Gitの設計文書は、そのような場合も扱うため、世代の比較だけで打ち切る一般条件を「候補より小さい」としています。図の探索順はGitが内部で実際に読んだ順番を表していません。<a href="https://git-scm.com/docs/commit-graph" target="_blank" rel="noreferrer">Gitのcommit-graph設計文書</a></p><h2 id="時計がずれても、親子の順序は変わらない" tabindex="-1">時計がずれても、親子の順序は変わらない <a class="header-anchor" href="#時計がずれても、親子の順序は変わらない" aria-label="Permalink to &quot;時計がずれても、親子の順序は変わらない&quot;">​</a></h2><p>別の端末でコミットすると、時計のずれによって子のコミッター時刻が親より古くなることがあります。図の <code>A</code>、<code>B</code>、<code>T</code> を例にします。時刻は同一の正の基準時刻からの秒数です。<code>B</code> の時刻105は親 <code>A</code> の110より小さいので、元の時刻だけを使うと <code>B</code> から <code>A</code> に届かないと誤判定します。v1は時刻を使いません。<a href="https://git-scm.com/docs/commit-graph" target="_blank" rel="noreferrer">Gitのcommit-graph設計文書</a></p><table tabindex="0"><thead><tr><th>コミット</th><th style="text-align:right;">元の時刻</th><th style="text-align:right;">v2（補正後）</th></tr></thead><tbody><tr><td><code>R</code></td><td style="text-align:right;">100</td><td style="text-align:right;">100</td></tr><tr><td><code>A</code></td><td style="text-align:right;">110</td><td style="text-align:right;">110</td></tr><tr><td><code>B</code></td><td style="text-align:right;">105</td><td style="text-align:right;">111</td></tr><tr><td><code>T</code></td><td style="text-align:right;">103</td><td style="text-align:right;">112</td></tr></tbody></table><p>世代番号v2は、元の時刻と「最も大きい親のv2に1秒を足した値」の大きい方です。<code>B</code> は <code>max(105, 110 + 1) = 111</code>、<code>T</code> は <code>max(103, 111 + 1) = 112</code> になります。親のないコミットは通常その元の時刻を使います（時刻0は未計算の印と区別するため1）。補正は索引の値にだけ適用され、オブジェクトに記録した時刻やOIDは変わりません。v1・v2は世代番号の定義で、索引ファイル自体の形式バージョンとは別です。<a href="https://git-scm.com/docs/commit-graph" target="_blank" rel="noreferrer">Gitのcommit-graph設計文書</a> · <a href="https://git-scm.com/docs/gitformat-commit-graph" target="_blank" rel="noreferrer">Gitのcommit-graphファイル形式</a></p><h2 id="特定パスの変更を探すときは別の最適化がある" tabindex="-1">特定パスの変更を探すときは別の最適化がある <a class="header-anchor" href="#特定パスの変更を探すときは別の最適化がある" aria-label="Permalink to &quot;特定パスの変更を探すときは別の最適化がある&quot;">​</a></h2><p>索引には、第1親との差で変わったパスの <strong>Bloom filter</strong> を追加できます。たとえば <code>git log -- player.cpp</code> が調べる途中で、対象パスは変わっていないと分かれば比較を省けます。フィルターが「変更の可能性あり」と返した場合には、実際の比較で確かめます。世代番号が答えるのは、親をたどって候補に届く可能性です。<a href="https://git-scm.com/docs/gitformat-commit-graph" target="_blank" rel="noreferrer">Gitのcommit-graphファイル形式</a> · <a href="https://git-scm.com/docs/git-commit-graph" target="_blank" rel="noreferrer">git commit-graphの <code>--changed-paths</code></a></p><h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2><ul><li>commit-graphは、元のオブジェクトから再生成できる索引です。親の位置を直接引けるので、オブジェクトの展開と解析を省けます。</li><li>祖先候補より世代番号が小さい地点に来たら、その向こうの親を調べる必要はありません。世代が同じときはコミットIDで一致を確かめます。</li><li>v1は親関係から求め、v2は親子の順序を保つようコミッター時刻を補正します。元のコミット時刻は変わりません。</li><li>変更パスのBloom filterが省くのはファイルの変更有無を調べる比較です。</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><details class="details custom-block"><summary><code>M</code> から <code>T</code> を探すとき、<code>Y</code> の親を読む必要がないのはなぜ？</summary><p><code>Y</code> の世代は3で、<code>T</code> の4より小さいためです。親をたどるほど図の世代番号は小さくなります。</p></details><details class="details custom-block"><summary><code>B</code> の時刻が親 <code>A</code> より古いとき、v2は元の時刻を書き換える？</summary><p>元の時刻とOIDはそのままです。索引で使う <code>B</code> のv2は、<code>A</code> のv2に1秒を足した111になります。</p></details><h2 id="検証範囲" tabindex="-1">検証範囲 <a class="header-anchor" href="#検証範囲" aria-label="Permalink to &quot;検証範囲&quot;">​</a></h2><p>2026年11月21日にGit公式資料を確認しました。Git for Windows 2.39.2.windows.1で、図と同じ8コミットを独立したSHA-1のリポジトリに作り、全64組の祖先判定を <code>git merge-base --is-ancestor</code> で比較しました。索引の生成前・生成後・退避後・再生成後で結果は一致しました。<code>git commit-graph verify</code> が通り、索引ファイルから読み出した親の位置とv1・v2も図の親関係と計算結果に一致しました。実際の読み出し回数や処理時間、Bloom filterの効果は測定していません。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/tools/git-changed-path-bloom-filter.html">Gitのchanged-path Bloom filter</a> — 特定のファイルの履歴を探すとき、第1親とのtree比較を省ける条件を読む。</li><li><a href="/study/tools/git-objects.html">Gitの保存モデル</a> — commitオブジェクトが親やtreeをどう参照するかを読む。</li><li><a href="/study/tools/git-three-way-merge.html">Gitのマージ</a> — 共通祖先を使ってマージの基準を探す場面を追う。</li><li><a href="/study/tools/git-reflog.html">Gitのreflog</a> — 参照の移動の記録と、コミットの親をたどる履歴を区別する。</li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://git-scm.com/docs/commit-graph" target="_blank" rel="noreferrer">Git — commit-graph設計文書</a> — 親の探索、世代番号、探索を打ち切る条件。</li><li><a href="https://git-scm.com/docs/gitformat-commit-graph" target="_blank" rel="noreferrer">Git — gitformat-commit-graph</a> — OIDと親の位置、世代番号、パスのBloom filterのファイル形式。</li><li><a href="https://git-scm.com/docs/git-commit-graph" target="_blank" rel="noreferrer">Git — git commit-graph</a> · <a href="https://git-scm.com/docs/git-merge-base" target="_blank" rel="noreferrer">git merge-base</a> — 索引の生成・検証と祖先判定。</li></ul>',20))])}const _=c(g,[["render",n]]);export{u as __pageData,_ as default};
